window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-7346dcd0e399aff7"]={"versions": [{"id": "FIG-7346dcd0e399aff7", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">SPEM-basiertes Methodik-Aktivitätsdiagramm (AUTOSAR Methodology Task Description). Das Diagramm visualisiert die Aktivitäten, Rollen sowie Ein- und Ausgangs-Arbeitsergebnisse (Work Products / Deliverables) für den Methodenschritt zur Definition von End-to-End-Absicherungsdefinitionen (E2E Protection Sets) für Software-Komponenten im VFB-Kontext (Virtual Function Bus).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrale Aktivität ist der Task <code>Define E2E Protection Set for Swc</code>.</p>\n<p class=\"fig-p\">Beteiligte Rolle:</p>\n<ul class=\"fig-list\">\n<li><code>Software Component Designer</code>: Führt die Aktivität aus (<code>«performs»</code>).</li>\n</ul>\n<p class=\"fig-p\">Eingangsartefakte (<code>«input»</code>):</p>\n<ul class=\"fig-list\">\n<li><code>VFB Atomic Software Component</code> (Kardinalität <code>1..*</code>)</li>\n<li><code>Types</code> (bzw. Datentypen, links abgeschnitten als <code>Types</code> dargestellt; Kardinalität <code>1..*</code>)</li>\n<li><code>VFB Interfaces</code> (Kardinalität <code>1..*</code>)</li>\n<li><code>VFB Top Level System Composition</code> (Kardinalität <code>1</code>)</li>\n<li><code>VFB Composition</code> (unten abgeschnitten; Kardinalität <code>0..*</code>)</li>\n</ul>\n<p class=\"fig-p\">Ausgangsartefakt (<code>«output»</code>):</p>\n<ul class=\"fig-list\">\n<li><code>E2E Protection Set</code> (Kardinalität <code>1</code>)</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der <code>Software Component Designer</code> initiiert und durchführt den Task <code>Define E2E Protection Set for Swc</code>. Als verpflichtende Basis werden die Systemkomposition (<code>VFB Top Level System Composition</code>, genau 1), mindestens eine atomare Software-Komponente (<code>VFB Atomic Software Component</code>, 1..<em>), mindestens ein VFB-Interface (<code>VFB Interfaces</code>, 1..</em>) sowie Typdefinitionen (<code>Types</code>, 1..<em>) herangezogen; optional bzw. ergänzend können hierarchische Sub-Kompositionen (<code>VFB Composition</code>, 0..</em>) einfließen. Auf Grundlage dieser Kommunikationsbeziehungen und Schnittstellenbeschreibungen wird genau ein konsistentes Artefakt <code>E2E Protection Set</code> erzeugt.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Der Task ist integraler Bestandteil des AUTOSAR-Entwicklungsprozesses für sicherheitsrelevante Kommunikationsbeziehungen (ISO 26262 E2E-Schutzprofilierung). Entwickler müssen sicherstellen, dass vor Ausführung dieses Tasks die VFB-Architektur (Top Level System Composition, Interfaces, SWC-Ports und Datentypen) konsistent spezifiziert ist. Das generierte <code>E2E Protection Set</code> bildet die verbindliche Vorgabe für nachgelagerte Schritte zur Konfiguration der E2E-Protection in RTE, COM und spezifischen E2E-Bibliotheksmodulen.</p>"}, {"id": "FIG-24a9468e1ddea1b8", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">SPEM-basiertes Methodik-Aktivitätsdiagramm (AUTOSAR Methodology Task Description). Das Diagramm visualisiert die Aktivitäten, Rollen sowie Ein- und Ausgangs-Arbeitsergebnisse (Work Products / Deliverables) für den Methodenschritt zur Definition von End-to-End-Absicherungsdefinitionen (E2E Protection Sets) für Software-Komponenten im VFB-Kontext (Virtual Function Bus).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrale Aktivität ist der Task <code>Define E2E Protection Set for Swc</code>.</p>\n<p class=\"fig-p\">Beteiligte Rolle:</p>\n<ul class=\"fig-list\">\n<li><code>Software Component Designer</code>: Führt die Aktivität aus (<code>«performs»</code>).</li>\n</ul>\n<p class=\"fig-p\">Eingangsartefakte (<code>«input»</code>):</p>\n<ul class=\"fig-list\">\n<li><code>VFB Atomic Software Component</code> (Kardinalität <code>1..*</code>)</li>\n<li><code>Types</code> (bzw. Datentypen, links abgeschnitten als <code>Types</code> dargestellt; Kardinalität <code>1..*</code>)</li>\n<li><code>VFB Interfaces</code> (Kardinalität <code>1..*</code>)</li>\n<li><code>VFB Top Level System Composition</code> (Kardinalität <code>1</code>)</li>\n<li><code>VFB Composition</code> (unten abgeschnitten; Kardinalität <code>0..*</code>)</li>\n</ul>\n<p class=\"fig-p\">Ausgangsartefakt (<code>«output»</code>):</p>\n<ul class=\"fig-list\">\n<li><code>E2E Protection Set</code> (Kardinalität <code>1</code>)</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der <code>Software Component Designer</code> initiiert und durchführt den Task <code>Define E2E Protection Set for Swc</code>. Als verpflichtende Basis werden die Systemkomposition (<code>VFB Top Level System Composition</code>, genau 1), mindestens eine atomare Software-Komponente (<code>VFB Atomic Software Component</code>, 1..<em>), mindestens ein VFB-Interface (<code>VFB Interfaces</code>, 1..</em>) sowie Typdefinitionen (<code>Types</code>, 1..<em>) herangezogen; optional bzw. ergänzend können hierarchische Sub-Kompositionen (<code>VFB Composition</code>, 0..</em>) einfließen. Auf Grundlage dieser Kommunikationsbeziehungen und Schnittstellenbeschreibungen wird genau ein konsistentes Artefakt <code>E2E Protection Set</code> erzeugt.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Der Task ist integraler Bestandteil des AUTOSAR-Entwicklungsprozesses für sicherheitsrelevante Kommunikationsbeziehungen (ISO 26262 E2E-Schutzprofilierung). Entwickler müssen sicherstellen, dass vor Ausführung dieses Tasks die VFB-Architektur (Top Level System Composition, Interfaces, SWC-Ports und Datentypen) konsistent spezifiziert ist. Das generierte <code>E2E Protection Set</code> bildet die verbindliche Vorgabe für nachgelagerte Schritte zur Konfiguration der E2E-Protection in RTE, COM und spezifischen E2E-Bibliotheksmodulen.</p>"}], "trans": [{"from": "FIG-7346dcd0e399aff7", "to": "FIG-24a9468e1ddea1b8", "fr": "R4.0.3", "tr": "R4.1.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
